def read(p):
 fd=os.open(str(p),os.O_RDONLY|os.O_NOATIME|os.O_NOFOLLOW)
 try:
  assert os.fstat(fd).st_size<1048576
  with os.fdopen(fd,'rb',closefd=False) as f:return f.read()
 finally:os.close(fd)
def sha(b):return hashlib.sha256(b).hexdigest()
def h(p):
 b=read(p);return {'sha256':sha(b),'bytes':len(b)}
def j(p):return json.loads(read(p))
